"""xArm+xHand mimic tasks."""

import gymnasium as gym

from ConTrack.tasks.manager_based.mimic_xarm_xhand import agents

gym.register(
    id="Isaac-Xarm-Xhand-Mimic-Manager-v0",
    entry_point="isaaclab.envs:ManagerBasedRLEnv",
    disable_env_checker=True,
    kwargs={
        "env_cfg_entry_point": f"{__name__}.xarm_xhand_env_cfg:XarmXhandEnvCfg",
        "rsl_rl_cfg_entry_point": f"{agents.__name__}.rsl_rl_ppo_cfg:PPORunnerCfg",
    },
)

gym.register(
    id="Isaac-Xarm-Xhand-Mimic-Manager-Play-v0",
    entry_point="isaaclab.envs:ManagerBasedRLEnv",
    disable_env_checker=True,
    kwargs={
        "env_cfg_entry_point": f"{__name__}.xarm_xhand_env_cfg:XarmXhandPlayEnvCfg",
        "rsl_rl_cfg_entry_point": f"{agents.__name__}.rsl_rl_ppo_cfg:PPORunnerCfg",
    },
)
